      'https://www.googleapis.com/calendar/v3/calendars/' + encodeURIComponent(settings['Calendar ID']) +
      '/events?singleEvents=true&maxResults=50&timeMin=' + encodeURIComponent(addMinutes(start, -buffer).toISOString()) +
