}

/** UTC instant for a wall-clock time in a time zone (handles DST). */
function zonedToUtc(year, month, day, hour, minute, tz) {
  let guess = Date.UTC(year, month - 1, day, hour, minute);
  for (let i = 0; i < 3; i++) {
    const p = zonedParts(new Date(guess), tz);
    const shown = Date.UTC(p.year, p.month - 1, p.day, p.hour, p.minute);
    const wanted = Date.UTC(year, month - 1, day, hour, minute);
    if (shown === wanted) break;
    guess += wanted - shown;
  }
  return new Date(guess);
}

function isValidTimeZone(tz) {
  try {
    new Intl.DateTimeFormat('en-GB', { timeZone: tz });
    return true;
  } catch (e) {
    return false;
  }
}

function hhmm(text, fallback) {
  const m = /^(\d{1,2}):(\d{2})$/.exec(str(text));
  if (!m) return fallback;
  const h = +m[1];
  const mi = +m[2];
  return h < 24 && mi < 60 ? { h, mi } : fallback;
}

/** Reads the opening-hours part of Settings into one object. */
function hoursFrom(settings) {
  const days = Array.isArray(settings['Opening Days']) && settings['Opening Days'].length
    ? settings['Opening Days']
    : ['Mon', 'Tue', 'Wed', 'Thu', 'Fri'];
  return {
    tz: str(settings['Business Timezone']),
    days,
    open: hhmm(settings['Opening Time'], { h: 8, mi: 0 }),
    close: hhmm(settings['Closing Time'], { h: 17, mi: 0 }),
  };
}

function isOpenDay(date, hours) {
  return hours.days.includes(zonedParts(date, hours.tz).weekday);
}

/** Opening time on the n-th business day after `from` (n=0: same day if open). */
function businessDayAt(from, n, hours, at) {
  const time = at || hours.open;
  let p = zonedParts(from, hours.tz);
  let cursor = zonedToUtc(p.year, p.month, p.day, 12, 0, hours.tz);
  let remaining = n;
  for (let guard = 0; guard < 60; guard++) {
    if (isOpenDay(cursor, hours)) {
      if (remaining === 0) {
        p = zonedParts(cursor, hours.tz);
        return zonedToUtc(p.year, p.month, p.day, time.h, time.mi, hours.tz);
      }
      remaining--;
    }
    cursor = new Date(cursor.getTime() + 24 * 3600 * 1000);
  }
  throw new Error('No opening days configured');
}

/** True when the instant is inside opening hours on an opening day. */
function isWithinHours(date, hours) {
  if (!isOpenDay(date, hours)) return false;
  const p = zonedParts(date, hours.tz);
  const mins = p.hour * 60 + p.minute;
  return mins >= hours.open.h * 60 + hours.open.mi && mins <= hours.close.h * 60 + hours.close.mi;
}

/** Next moment the business is open (now, if open now). */
function nextOpenMoment(now, hours) {
  if (isWithinHours(now, hours)) return now;
  const p = zonedParts(now, hours.tz);
  const mins = p.hour * 60 + p.minute;
  // Closed day, or before opening on an open day: the next opening is the first open day (n=0). After closing: the following one.
  const sameOrNext = !isOpenDay(now, hours) || mins < hours.open.h * 60 + hours.open.mi;
  return businessDayAt(now, sameOrNext ? 0 : 1, hours);
}

function addDays(date, days) {
  return new Date(date.getTime() + days * 24 * 3600 * 1000);
}

function addMinutes(date, mins) {
  return new Date(date.getTime() + mins * 60 * 1000);
}

/** Customer-friendly date/time in the business time zone. */
function friendly(date, tz) {
  return new Intl.DateTimeFormat('en-GB', {
    timeZone: tz,
    weekday: 'long',
    day: 'numeric',
    month: 'long',
    hour: 'numeric',
    minute: '2-digit',
    hour12: true,
  }).format(date);
}

/** Adds a key to a newline-separated list field, without duplicates. */
function addToList(text, value) {
  const items = str(text).split('\n').map((s) => s.trim()).filter(Boolean);
  if (value && !items.includes(value)) items.push(value);
  return items.join('\n');
}

function hasInList(text, value) {
  return str(text).split('\n').map((s) => s.trim()).includes(value);
}

/** Google Calendar event IDs must use characters a-v and 0-9. */
function calendarEventId(recordId) {
  let hex = '';
  for (const ch of String(recordId)) hex += ch.charCodeAt(0).toString(16).padStart(2, '0');
  return 'rfi' + hex;
}

/** Plain-language Airtable error text from an HTTP response (fullResponse mode). */
function httpProblem(res) {
  const code = res && res.statusCode;
  const body = (res && res.body) || {};
  const err = body.error;
  const detail = typeof err === 'string' ? err : (err && (err.message || err.type)) || '';
  return 'HTTP ' + (code || 'no response') + (detail ? ': ' + String(detail).slice(0, 200) : '');
}

function ok(res) {
  return res && res.statusCode >= 200 && res.statusCode < 300;
}

/** A "needs help" item for the ROOFORA error workflow (never includes customer details). */
function problemOf(step, ref, leadId, problem, action, executionId) {
  return { source: 'handled', step, ref: ref || '', leadId: leadId || '', problem: String(problem || ''), action: action || '', executionId: executionId || '' };
}

// ROOFORA automation — website enquiry intake and qualification.
// Depends on core.js (pasted before this file).

const INTAKE = {
  propertyTypes: ['Residential', 'Commercial', 'Other'],
  services: ['Roof Installation', 'Roof Repair', 'Roof Replacement', 'Commercial Roofing', 'Storm & Leak Response', 'Roof Inspections', 'Not sure yet'],
  urgencies: ['Urgent active leak/storm damage', 'This week', 'This month', 'Just researching'],
  urgent: 'Urgent active leak/storm damage',
  environments: ['development', 'preview', 'production'],
  allowedKeys: ['contractVersion', 'source', 'environment', 'enquiryRef', 'receivedAt', 'submissionId', 'fullName', 'phone', 'email', 'propertyType', 'service', 'town', 'postcode', 'details', 'urgency', 'preferredContact', 'photoCount', 'consent'],
};

/** Reads the single Settings row and reports anything that needs fixing. */
function readSettings(res) {
  const problems = [];
  const rec = res && res.body && Array.isArray(res.body.records) ? res.body.records[0] : null;
  if (!ok(res) || !rec) {
    problems.push('Settings could not be read (' + httpProblem(res) + '). Safe defaults were used and no customer email was sent.');
  }
  const s = Object.assign({}, rec ? rec.fields : {});
  if (!isValidTimeZone(str(s['Business Timezone']))) {
    if (rec) problems.push('Settings › Business Timezone "' + str(s['Business Timezone']) + '" is not a valid time zone name (e.g. Europe/London). UTC was used.');
    s['Business Timezone'] = 'UTC';
  }
  // Without readable settings, never send customer emails.
  if (!rec) s['Customer Emails Enabled'] = false;
  return { settings: s, problems, recordId: rec ? rec.id : null };
}

/** Checks the website → n8n payload. Returns { valid, errors, data }. */
function checkEnquiryPayload(body) {
  const errors = {};
  const b = body && typeof body === 'object' ? body : {};
  for (const key of Object.keys(b)) {
    if (!INTAKE.allowedKeys.includes(key)) errors._unexpected = 'Unexpected field: ' + key;
  }
  const sid = str(b.submissionId);
  if (!/^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/.test(sid)) errors.submissionId = 'Invalid submission ID.';
  if (b.contractVersion !== 1) errors.contractVersion = 'Unsupported contract version.';
  const fullName = str(b.fullName, 100);
  if (fullName.length < 2) errors.fullName = 'Please enter your full name.';
  const phone = str(b.phone, 30);
  if (!/^\+?\d{7,15}$/.test(phone)) errors.phone = 'Please enter a valid phone number.';
  const preferred = b.preferredContact === 'Email' ? 'Email' : b.preferredContact === 'Phone' ? 'Phone' : '';
  if (!preferred) errors.preferredContact = 'Please choose a contact method.';
  const email = str(b.email, 200).toLowerCase();
  if (preferred === 'Email' && !email) errors.email = 'Please enter your email address.';
  if (email && !/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email)) errors.email = 'Please enter a valid email address.';
  if (!INTAKE.propertyTypes.includes(b.propertyType)) errors.propertyType = 'Please choose a property type.';
  if (!INTAKE.services.includes(b.service)) errors.service = 'Please choose a service.';
  const town = str(b.town, 80);
  if (town.length < 2) errors.town = 'Please enter the town or city.';
  if (!INTAKE.urgencies.includes(b.urgency)) errors.urgency = 'Please tell us how soon you need help.';
  const consent = b.consent || {};
  if (consent.given !== true || !str(consent.wording) || !str(consent.version)) errors.consent = 'Contact permission is required.';
  const photoCount = Number(b.photoCount);
  if (!Number.isInteger(photoCount) || photoCount < 0 || photoCount > 3) errors.photos = 'Up to 3 photos.';
  const expectedRef = 'RF-' + sid.replace(/-/g, '').slice(0, 8).toUpperCase();
  if (sid && str(b.enquiryRef) !== expectedRef) errors.enquiryRef = 'Reference mismatch.';

  if (Object.keys(errors).length) return { valid: false, errors };
  return {
    valid: true,
    errors: {},
    data: {
      submissionId: sid,
      enquiryRef: expectedRef,
      receivedAt: isNaN(Date.parse(b.receivedAt)) ? new Date().toISOString() : new Date(b.receivedAt).toISOString(),
      environment: INTAKE.environments.includes(b.environment) ? b.environment : 'development',
      fullName,
      phone,
      email: email || null,
      preferredContact: preferred,
      propertyType: b.propertyType,
      service: b.service,
      town,
      postcode: str(b.postcode, 12).toUpperCase() || null,
      details: str(b.details, 2000) || null,
      urgency: b.urgency,
      photoCount,
      consent: { wording: str(consent.wording, 500), version: str(consent.version, 60), recordedAt: isNaN(Date.parse(consent.recordedAt)) ? new Date().toISOString() : new Date(consent.recordedAt).toISOString() },
    },
  };
}

function normalisePostcode(v) {
  return str(v).toUpperCase().replace(/[^A-Z0-9 ]/g, '').replace(/\s+/g, ' ').trim();
}

/** Outward code: the part before the space (UK style), or all but the last 3 characters when typed without a space. */
function outwardCode(postcode) {
  const pc = normalisePostcode(postcode);
  if (pc.includes(' ')) return pc.split(' ')[0];
  return pc.length >= 5 ? pc.slice(0, -3) : pc;
}

/**
 * A prefix ending in a digit (SE1, CR0) must equal the outward code, so SE1 never matches SE10.
 * A letters-only prefix (SW, CR) matches any outward code that continues with a digit (SW19).
 */
function postcodeMatches(postcode, prefix) {
  const out = outwardCode(postcode);
  const pre = normalisePostcode(prefix).replace(/ /g, '');
  if (!out || !pre) return false;
  if (out === pre) return true;
  return /^[A-Z]+$/.test(pre) && out.startsWith(pre) && /\d/.test(out[pre.length] || '');
}

/** Service-area check. Never returns "Out of Area" — only staff decide that. */
function checkServiceArea(town, postcode, settings) {
  const prefixes = list(settings['Service Area Postcode Prefixes']);
  const towns = list(settings['Service Area Towns']).map((t) => t.toLowerCase());
  if (!prefixes.length && !towns.length) return { area: 'Not Checked', note: 'No service area is set in Settings.' };
  const pcMatch = postcode ? prefixes.some((p) => postcodeMatches(postcode, p)) : false;
  const townMatch = towns.includes(str(town).toLowerCase());
  if (pcMatch) return { area: 'In Area', note: 'Postcode is inside the service area.' };
  if (townMatch && (!postcode || !prefixes.length)) return { area: 'In Area', note: 'Town is inside the service area.' };
  if (townMatch) return { area: 'Needs Review', note: 'Town is listed but the postcode is not; please check.' };
  if (postcode && prefixes.length) return { area: 'Possibly Out of Area', note: 'Postcode not in the listed area; please check before replying.' };
  return { area: 'Needs Review', note: 'Location could not be matched automatically; please check.' };
}

/** Owner, priority, next action and follow-up plan for a new lead. */
function qualifyLead(data, settings, now) {
  const hours = hoursFrom(settings);
  const urgent = data.urgency === INTAKE.urgent;
  const area = checkServiceArea(data.town, data.postcode, settings);
  const owner = (urgent && str(settings['Urgent Owner'])) || str(settings['Default Owner']) || 'Office';
  const checkArea = area.area === 'Needs Review' || area.area === 'Possibly Out of Area';
  const phonePref = data.preferredContact === 'Phone';

  let nextAction;
  let due;
  if (urgent) {
    nextAction = 'URGENT: call customer back' + (checkArea ? ' (check service area)' : '');
    due = now;
  } else if (phonePref) {
    nextAction = (checkArea ? 'Check service area, then ' : '') + 'call customer back to arrange an inspection';
    due = addMinutes(nextOpenMoment(now, hours), 240);
  } else {
    nextAction = (checkArea ? 'Check service area, then ' : '') + 'email customer to arrange an inspection';
    due = addMinutes(nextOpenMoment(now, hours), 240);
  }

  const followDays = numberList(settings['Enquiry Follow-up Business Days'], [1, 3]);
  return {
    priority: urgent ? 'Urgent' : 'Normal',
    urgent,
    owner,
    area,
    nextAction,
    nextActionDue: due.toISOString(),
    followUp: {
      status: 'Active',
      kind: 'Enquiry',
      step: 0,
      nextAt: businessDayAt(now, followDays[0], hours).toISOString(),
    },
    sendAcknowledgement: !phonePref && Boolean(data.email),
    callbackTask: phonePref || urgent,
  };
}

/** Airtable fields for the new lead (create only; never used to overwrite). */
function leadFields(data, q) {
  return {
    'Enquiry Ref': data.enquiryRef,
    'Submission ID': data.submissionId,
    'Received At': data.receivedAt,
    Environment: data.environment,
    'Full Name': data.fullName,
    Phone: data.phone,
    Email: data.email || undefined,
    'Preferred Contact': data.preferredContact,
    'Property Type': data.propertyType,
    Service: data.service,
    Town: data.town,
    Postcode: data.postcode || undefined,
    'Roof Details': data.details || undefined,
    Urgency: data.urgency,
    Priority: q.priority,
    'Photos Expected': data.photoCount,
    'Contact Permission': true,
    'Permission Wording': data.consent.wording,
    'Permission Version': data.consent.version,
    'Permission Recorded At': data.consent.recordedAt,
    Stage: 'New',
    'Service Area': q.area.area,
    Owner: q.owner,
    'Next Action': q.nextAction,
    'Next Action Due': q.nextActionDue,
    'Follow-up Status': q.followUp.status,
    'Follow-up Kind': q.followUp.kind,
    'Follow-up Step': q.followUp.step,
    'Follow-up Base At': data.receivedAt,
    'Next Follow-up At': q.followUp.nextAt,
  };
}

/**
 * Duplicate guard after creating a lead. Every execution that created a row
 * for this Submission ID looks at all rows with that ID; only the earliest
 * (createdTime, then record ID) carries on. Later rows mark themselves as
 * duplicates and send nothing.
 */
function pickWinner(records) {
  const sorted = records.slice().sort((a, b) => {
    const t = Date.parse(a.createdTime) - Date.parse(b.createdTime);
    return t !== 0 ? t : a.id < b.id ? -1 : 1;
  });
  return sorted[0];
}

function telegramNewLead(data, q, leadUrl) {
  const lines = [
    (q.urgent ? '🚨 URGENT roofing enquiry ' : '🏠 New roofing enquiry ') + data.enquiryRef + (data.environment !== 'production' ? ' [' + data.environment.toUpperCase() + ']' : ''),
    data.fullName + ' — ' + data.service + ' (' + data.propertyType + ')',
    'Where: ' + data.town + (data.postcode ? ' ' + data.postcode : '') + ' · Area: ' + q.area.area,
    'How soon: ' + data.urgency,
    'Prefers: ' + (data.preferredContact === 'Phone' ? 'phone call — ' + data.phone : 'email'),
    data.photoCount ? 'Photos: ' + data.photoCount + ' uploading' : null,
    'Owner: ' + q.owner + ' · Next: ' + q.nextAction,
    q.urgent ? 'Reminder: nothing has promised the customer an emergency visit.' : null,
    leadUrl ? 'Open: ' + leadUrl : null,
  ];
  return lines.filter(Boolean).join('\n');
}

// ROOFORA automation — staff actions started from Airtable buttons.
// Depends on core.js, email.js.

const STAFF_ACTIONS = {
  'book-inspection': { table: 'Inspections', label: 'Book or move this inspection' },
  'cancel-inspection': { table: 'Inspections', label: 'Cancel this inspection' },
  'complete-inspection': { table: 'Inspections', label: 'Mark this inspection as completed' },
  'send-quote': { table: 'Quotes', label: 'Send this approved quote' },
  'record-accepted': { table: 'Quotes', label: 'Record that the customer ACCEPTED this quote' },
  'record-declined': { table: 'Quotes', label: 'Record that the customer DECLINED this quote' },
};

function esc(v) {
  return String(v === undefined || v === null ? '' : v)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

function page(title, bodyHtml, tone) {
  const colour = tone === 'bad' ? '#b42318' : tone === 'good' ? '#067647' : '#1e1e1e';
  return (
    '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">' +
    '<meta name="robots" content="noindex"><title>' + esc(title) + ' · ROOFORA</title>' +
    '<style>body{font-family:system-ui,sans-serif;background:#f7f3ee;color:#1e1e1e;margin:0;padding:24px}' +
    'main{max-width:560px;margin:40px auto;background:#fff;border-radius:16px;padding:28px;box-shadow:0 10px 30px rgba(0,0,0,.08)}' +
    'h1{font-size:22px;margin:0 0 12px;color:' + colour + '}dl{display:grid;grid-template-columns:auto 1fr;gap:6px 14px;margin:16px 0}' +
    'dt{font-weight:600;color:#555}dd{margin:0;white-space:pre-line}button{font:inherit;font-weight:700;background:#ff8537;color:#fff;border:0;border-radius:999px;padding:14px 26px;cursor:pointer;min-height:48px}' +
    'button:focus-visible{outline:3px solid #1e1e1e;outline-offset:2px}.note{color:#555;font-size:14px}</style></head><body><main>' +
    '<h1>' + esc(title) + '</h1>' + bodyHtml + '</main></body></html>'
  );
}

/** Validates ?action=&record= from the button URL. */
function readStaffRequest(q) {
  const action = str(q && q.action);
  const record = str(q && q.record);
  if (!STAFF_ACTIONS[action]) return { valid: false, html: page('Unknown action', '<p>This button is not set up correctly. Check the button URL in Airtable.</p>', 'bad') };
  if (!/^rec[A-Za-z0-9]{14}$/.test(record)) return { valid: false, html: page('Missing record', '<p>The button did not send a record ID.</p>', 'bad') };
  return { valid: true, action, record, table: STAFF_ACTIONS[action].table };
}

/** Confirmation page shown on GET; nothing changes until the button is pressed. */
function confirmPage(req, rec, settings) {
  const f = (rec && rec.fields) || {};
  const tz = str(settings['Business Timezone']) || 'UTC';
  const rows = [];
  if (req.table === 'Inspections') {
    rows.push(['Inspection', f.Inspection], ['Status', f.Status || 'Requested']);
    if (f['Proposed Start']) rows.push(['Proposed time', friendly(new Date(f['Proposed Start']), tz)]);
    if (f['Confirmed Start']) rows.push(['Currently booked', friendly(new Date(f['Confirmed Start']), tz)]);
  } else {
    rows.push(['Quote', f.Quote], ['Version', f.Version], ['Amount', f.Amount], ['Approved', f.Approved ? 'Yes, by ' + (f['Approved By'] || '?') : 'No'], ['Status', f.Status || 'Draft']);
  }
  const dl = '<dl>' + rows.map((r) => '<dt>' + esc(r[0]) + '</dt><dd>' + esc(r[1]) + '</dd>').join('') + '</dl>';
  const form =
    '<form method="post"><input type="hidden" name="action" value="' + esc(req.action) + '">' +
    '<input type="hidden" name="record" value="' + esc(req.record) + '"><button type="submit">' + esc(STAFF_ACTIONS[req.action].label) + '</button></form>' +
    '<p class="note">Nothing has changed yet. Close this tab to cancel.</p>';
  return page(STAFF_ACTIONS[req.action].label, dl + form);
}

/**
 * The POST must come from the confirmation page (same origin) — blocks other
 * websites from triggering staff actions with a saved browser login.
 */
function checkStaffOrigin(headers, n8nBaseUrl) {
  const origin = str(headers && (headers.origin || headers.Origin));
  const expected = str(n8nBaseUrl).replace(/\/+$/, '');
  if (!origin || !expected) return false;
  // n8n's Code-node sandbox has no URL global, so compare "scheme://host[:port]" with a plain pattern.
  const m = /^(https?:\/\/[^/?#]+)/i.exec(expected);
  return Boolean(m) && origin.toLowerCase() === m[1].toLowerCase();
}

function leadIdOf(rec) {
  const l = rec && rec.fields && rec.fields.Lead;
  return Array.isArray(l) && l.length ? l[0] : null;
}

// ---------------- inspections ----------------

/** Decides what a "Book" press should do. */
function planBooking(insp, lead, settings, now) {
  const f = insp.fields;
  const tz = str(settings['Business Timezone']) || 'UTC';
  const hours = hoursFrom(settings);
  const fail = (msg) => ({ go: false, message: msg });
  if (!str(settings['Calendar ID'])) return fail('Settings › Calendar ID is empty, so nothing can be booked.');
  if (!lead) return fail('This inspection is not linked to a lead.');
  if (f.Status === 'Completed') return fail('This inspection is already completed. Create a new inspection record to book another visit.');
  if (!f['Proposed Start']) return fail('Enter a Proposed Start time first.');
  const start = new Date(f['Proposed Start']);
  if (isNaN(start)) return fail('Proposed Start is not a valid date and time.');
  if (start.getTime() < now.getTime() + 30 * 60000) return fail('The proposed time is in the past or less than 30 minutes away.');
  const minutes = Number(f['Duration Minutes']) || Number(settings['Inspection Duration Minutes']) || 60;
  const end = addMinutes(start, minutes);
  if (!isWithinHours(start, hours) || !isWithinHours(end, hours) || zonedParts(start, tz).day !== zonedParts(end, tz).day) {
    return fail('The proposed time (' + friendly(start, tz) + ', ' + minutes + ' min) is outside opening hours in Settings.');
  }
  const version = Number(f['Booking Version']) || 0;
  const alreadyBooked = f.Status === 'Scheduled' && f['Confirmed Start'] && new Date(f['Confirmed Start']).getTime() === start.getTime();
  if (alreadyBooked) return { go: false, unchanged: true, message: 'Already booked for ' + friendly(start, tz) + '. Nothing changed.' };
  const buffer = Number(settings['Travel Buffer Minutes']) || 0;
  const eventId = str(f['Calendar Event ID']) || calendarEventId(insp.id);
  const isMove = f.Status === 'Scheduled' && Boolean(f['Confirmed Start']);
  return {
    go: true,
    isMove,
    start: start.toISOString(),
    end: end.toISOString(),
    newVersion: version + 1,
    eventId,
    eventExists: Boolean(str(f['Calendar Event ID'])),
    checkUrl:
      'https://www.googleapis.com/calendar/v3/calendars/' + encodeURIComponent(settings['Calendar ID']) +
      '/events?singleEvents=true&maxResults=50&timeMin=' + encodeURIComponent(addMinutes(start, -buffer).toISOString()) +
      '&timeMax=' + encodeURIComponent(addMinutes(end, buffer).toISOString()),
  };
}

/** Any calendar event (other than this inspection's own) that blocks the slot. */
function findConflicts(res, ownEventId, tz) {
  if (!ok(res)) return { checked: false, message: 'Could not check the calendar (' + httpProblem(res) + '). Nothing was booked.' };
  const items = (res.body && res.body.items) || [];
  const clashes = items.filter((e) => e.id !== ownEventId && e.status !== 'cancelled' && e.transparency !== 'transparent');
  if (!clashes.length) return { checked: true, free: true };
  const first = clashes[0];
  const when = first.start && first.start.dateTime ? friendly(new Date(first.start.dateTime), tz) : 'an all-day event';
  return { checked: true, free: false, message: 'Not booked: the time clashes with "' + (first.summary || 'a calendar event') + '" (' + when + '), including travel buffer.' };
}

function eventBody(plan, lead, insp, settings) {
  const f = lead.fields;
  const tz = str(settings['Business Timezone']) || 'UTC';
  return {
